@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600&family=Oswald:wght@500;600;700&display=swap');

:root {
  --bg-color: #111111;
  --surface-color: #1a1a1a;
  --surface-hover: #2a2a2a;
  --text-primary: #ffffff;
  --text-secondary: #a0a0a0;
  --brand-red: #E63946;
  --brand-red-hover: #c42631;
  --border-color: #333333;

  --font-heading: 'Oswald', sans-serif;
  --font-body: 'Inter', sans-serif;

  --spacing-sm: 0.5rem;
  --spacing-md: 1rem;
  --spacing-lg: 2rem;
  --spacing-xl: 4rem;
  --spacing-2xl: 6rem;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-body);
  background-color: var(--bg-color);
  color: var(--text-primary);
  line-height: 1.6;
  overflow-x: hidden;
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  text-transform: uppercase;
  line-height: 1.1;
  letter-spacing: 0.05em;
  margin-bottom: var(--spacing-md);
}

h1 { font-size: clamp(3rem, 6vw, 5rem); }
h2 { font-size: clamp(2rem, 4vw, 3.5rem); }
h3 { font-size: clamp(1.5rem, 3vw, 2.5rem); }

a {
  color: var(--text-primary);
  text-decoration: none;
  transition: color 0.2s ease;
}

a:hover {
  color: var(--brand-red);
}

img {
  max-width: 100%;
  display: block;
}

.container {
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 var(--spacing-lg);
}

section {
  padding: var(--spacing-2xl) 0;
}

/* Utilities */
.text-center { text-align: center; }
.text-red { color: var(--brand-red); }
.bg-surface { background-color: var(--surface-color); }
.flex-between { display: flex; justify-content: space-between; align-items: center; }
.gap-md { gap: var(--spacing-md); }
.gap-lg { gap: var(--spacing-lg); }

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 1rem 2rem;
  font-family: var(--font-heading);
  font-size: 1.125rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  border: 2px solid transparent;
  cursor: pointer;
  transition: all 0.3s ease;
}

.btn-primary {
  background-color: var(--brand-red);
  color: #fff;
}

.btn-primary:hover {
  background-color: var(--brand-red-hover);
  color: #fff;
}

.btn-outline {
  background-color: transparent;
  border-color: var(--text-primary);
  color: var(--text-primary);
}

.btn-outline:hover {
  background-color: var(--text-primary);
  color: var(--bg-color);
}

/* Navigation */
.top-bar {
  background-color: var(--brand-red);
  color: #fff;
  text-align: center;
  padding: 0.5rem;
  font-size: 0.875rem;
  font-weight: 500;
}
.top-bar a {
  color: #fff;
  text-decoration: underline;
  margin-left: 0.5rem;
}

.navbar {
  position: sticky;
  top: 0;
  background-color: rgba(17, 17, 17, 0.95);
  backdrop-filter: blur(10px);
  z-index: 1000;
  border-bottom: 1px solid var(--border-color);
  padding: 1rem 0;
}

.nav-container {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.logo {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  color: var(--brand-red);
}

.nav-links {
  display: flex;
  gap: 1.5rem;
}

.nav-links a {
  font-size: 0.875rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.nav-actions {
  display: flex;
  gap: 1rem;
  align-items: center;
}

.mobile-menu-btn {
  display: none;
  background: none;
  border: none;
  color: #fff;
  font-size: 1.5rem;
  cursor: pointer;
}

@media (max-width: 992px) {
  .nav-links {
    display: none;
    position: absolute;
    top: 100%;
    left: 0;
    width: 100%;
    background-color: var(--bg-color);
    flex-direction: column;
    padding: 1rem;
    border-bottom: 1px solid var(--border-color);
  }
  .nav-links.active {
    display: flex;
  }
  .mobile-menu-btn {
    display: block;
  }
  .nav-actions {
    display: none;
  }
}

/* Hero Section */
.hero {
  min-height: 80vh;
  display: flex;
  align-items: center;
  position: relative;
  overflow: hidden;
  padding: 4rem 0;
}

.hero::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: linear-gradient(rgba(17,17,17,0.4), rgba(17,17,17,0.9)), url('https://images.unsplash.com/photo-1534438327276-14e5300c3a48?q=80&w=2000&auto=format&fit=crop') center/cover;
  z-index: -1;
}

.hero-content {
  max-width: 800px;
}

.hero-subtitle {
  font-size: 1.25rem;
  color: var(--text-secondary);
  margin-bottom: var(--spacing-lg);
  max-width: 600px;
}

.hero-actions {
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
}

/* Features / Split Sections */
.split-section {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--spacing-xl);
  align-items: center;
}

@media (max-width: 768px) {
  .split-section {
    grid-template-columns: 1fr;
  }
}

/* Carousel */
.carousel-section {
  position: relative;
  padding: var(--spacing-xl) 0;
  overflow: hidden;
}

.carousel-container {
  display: flex;
  transition: transform 0.4s ease;
  width: 100%;
}

.carousel-slide {
  min-width: 100%;
  flex: 0 0 100%;
  position: relative;
}

.carousel-slide img {
  width: 100%;
  height: 600px;
  object-fit: cover;
  opacity: 0.7;
}

.carousel-caption {
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  padding: 2rem;
  background: linear-gradient(transparent, var(--bg-color));
}

.carousel-controls {
  position: absolute;
  top: 50%;
  left: 0;
  width: 100%;
  display: flex;
  justify-content: space-between;
  padding: 0 var(--spacing-lg);
  transform: translateY(-50%);
  z-index: 10;
  pointer-events: none;
}

.carousel-btn {
  background: rgba(0,0,0,0.5);
  color: #fff;
  border: 1px solid var(--border-color);
  width: 50px;
  height: 50px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  pointer-events: auto;
  transition: all 0.2s;
}

.carousel-btn:hover {
  background: var(--brand-red);
  border-color: var(--brand-red);
}

/* Forms */
.newsletter-form {
  display: flex;
  max-width: 500px;
  margin: 0 auto;
  gap: 0.5rem;
}

.input-field {
  flex-grow: 1;
  padding: 1rem;
  background-color: var(--surface-color);
  border: 1px solid var(--border-color);
  color: var(--text-primary);
  font-family: var(--font-body);
  outline: none;
}

.input-field:focus {
  border-color: var(--brand-red);
}

.form-feedback {
  margin-top: 0.5rem;
  font-size: 0.875rem;
  display: none;
}
.form-feedback.success { color: #4caf50; display: block; }
.form-feedback.error { color: var(--brand-red); display: block; }

/* Footer */
footer {
  background-color: #000;
  padding: var(--spacing-xl) 0 var(--spacing-lg);
  border-top: 1px solid var(--border-color);
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: var(--spacing-lg);
  margin-bottom: var(--spacing-xl);
}

.footer-col h4 {
  font-size: 1.25rem;
  margin-bottom: 1.5rem;
  color: var(--text-primary);
}

.footer-col ul {
  list-style: none;
}

.footer-col li {
  margin-bottom: 0.75rem;
}

.footer-col a {
  color: var(--text-secondary);
  font-size: 0.875rem;
}

.footer-col a:hover {
  color: var(--brand-red);
}

.footer-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: var(--spacing-lg);
  border-top: 1px solid var(--border-color);
  color: var(--text-secondary);
  font-size: 0.875rem;
}

.country-select {
  position: relative;
}

.country-btn {
  background: transparent;
  color: var(--text-secondary);
  border: 1px solid var(--border-color);
  padding: 0.5rem 1rem;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.country-dropdown {
  position: absolute;
  bottom: 100%;
  right: 0;
  background: var(--surface-color);
  border: 1px solid var(--border-color);
  list-style: none;
  min-width: 150px;
  display: none;
  margin-bottom: 0.5rem;
}

.country-dropdown.active {
  display: block;
}

.country-dropdown li {
  padding: 0.5rem 1rem;
  cursor: pointer;
  transition: background 0.2s;
}

.country-dropdown li:hover {
  background: var(--surface-hover);
  color: var(--brand-red);
}

/* Instructor Grid */
.filter-bar {
  display: flex;
  gap: 1rem;
  margin-bottom: var(--spacing-lg);
  overflow-x: auto;
  padding-bottom: 1rem;
}

.filter-btn {
  background: var(--surface-color);
  border: 1px solid var(--border-color);
  color: var(--text-secondary);
  padding: 0.5rem 1.5rem;
  cursor: pointer;
  white-space: nowrap;
  font-family: var(--font-heading);
  text-transform: uppercase;
  transition: all 0.2s;
}

.filter-btn.active, .filter-btn:hover {
  background: var(--brand-red);
  color: #fff;
  border-color: var(--brand-red);
}

.instructor-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: var(--spacing-lg);
}

.instructor-card {
  background: var(--surface-color);
  border: 1px solid var(--border-color);
  transition: transform 0.3s ease;
}

.instructor-card:hover {
  transform: translateY(-5px);
  border-color: var(--brand-red);
}

.instructor-img {
  width: 100%;
  height: 300px;
  object-fit: cover;
  background-color: #333;
}

.instructor-info {
  padding: 1.5rem;
}

.instructor-name {
  font-size: 1.5rem;
  margin-bottom: 0.25rem;
}

.instructor-location {
  color: var(--text-secondary);
  font-size: 0.875rem;
  margin-bottom: 1rem;
}

/* Toggle (Floor / Treadmill) */
.toggle-wrapper {
  display: flex;
  background: var(--surface-color);
  border-radius: 40px;
  padding: 0.5rem;
  max-width: 400px;
  margin: 0 auto var(--spacing-lg);
}

.toggle-btn {
  flex: 1;
  background: transparent;
  border: none;
  color: var(--text-secondary);
  padding: 1rem;
  font-family: var(--font-heading);
  font-size: 1.25rem;
  cursor: pointer;
  border-radius: 30px;
  transition: all 0.3s;
}

.toggle-btn.active {
  background: var(--brand-red);
  color: #fff;
}

.toggle-content {
  display: none;
  animation: fadeIn 0.4s ease;
}

.toggle-content.active {
  display: block;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

/* FAQ Accordion */
.accordion {
  max-width: 800px;
  margin: 0 auto;
}

.accordion-item {
  border-bottom: 1px solid var(--border-color);
}

.accordion-header {
  width: 100%;
  background: transparent;
  border: none;
  color: var(--text-primary);
  text-align: left;
  padding: 1.5rem 0;
  font-family: var(--font-heading);
  font-size: 1.25rem;
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.accordion-icon {
  font-size: 1.5rem;
  color: var(--brand-red);
  transition: transform 0.3s ease;
}

.accordion-item.active .accordion-icon {
  transform: rotate(45deg);
}

.accordion-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease;
  color: var(--text-secondary);
}

.accordion-item.active .accordion-content {
  max-height: 500px;
}

.accordion-inner {
  padding-bottom: 1.5rem;
}

/* Table */
.schedule-table {
  width: 100%;
  border-collapse: collapse;
  margin-top: var(--spacing-lg);
}

.schedule-table th,
.schedule-table td {
  padding: 1.5rem;
  text-align: left;
  border-bottom: 1px solid var(--border-color);
}

.schedule-table th {
  font-family: var(--font-heading);
  color: var(--brand-red);
  font-size: 1.25rem;
}

.schedule-table tr:hover td {
  background-color: var(--surface-color);
}

/* Digital Features */
.feature-list {
  display: grid;
  grid-template-columns: 1fr;
  gap: 2rem;
  margin-top: 2rem;
}
.feature-item {
  background: var(--surface-color);
  padding: 2rem;
  border-left: 4px solid var(--brand-red);
}
.feature-item h3 {
  margin-bottom: 0.5rem;
}
.feature-item p {
  color: var(--text-secondary);
}

document.addEventListener('DOMContentLoaded', () => {
  // Mobile Menu
  const mobileMenuBtn = document.querySelector('.mobile-menu-btn');
  const navLinks = document.querySelector('.nav-links');
  if (mobileMenuBtn && navLinks) {
    mobileMenuBtn.addEventListener('click', () => {
      navLinks.classList.toggle('active');
    });
  }

  // Country Selector (Footer)
  const countryBtn = document.querySelector('.country-btn');
  const countryDropdown = document.querySelector('.country-dropdown');
  const currentCountry = document.querySelector('.current-country');

  if (countryBtn && countryDropdown) {
    countryBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      countryDropdown.classList.toggle('active');
    });

    countryDropdown.addEventListener('click', (e) => {
      if (e.target.tagName === 'LI') {
        if (currentCountry) {
          currentCountry.textContent = e.target.textContent;
        }
        countryDropdown.classList.remove('active');
      }
    });

    document.addEventListener('click', () => {
      countryDropdown.classList.remove('active');
    });
  }

  // Newsletter Form
  const newsletterForms = document.querySelectorAll('.newsletter-form');
  newsletterForms.forEach(form => {
    form.addEventListener('submit', (e) => {
      e.preventDefault();
      const input = form.querySelector('.input-field');
      const feedback = form.querySelector('.form-feedback');
      const email = input.value.trim();

      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

      if (emailRegex.test(email)) {
        feedback.textContent = 'Thanks for subscribing!';
        feedback.className = 'form-feedback success';
        input.value = '';
      } else {
        feedback.textContent = 'Please enter a valid email address.';
        feedback.className = 'form-feedback error';
      }
    });
  });

  // Carousel
  const carouselContainer = document.querySelector('.carousel-container');
  if (carouselContainer) {
    const slides = document.querySelectorAll('.carousel-slide');
    const prevBtn = document.querySelector('.carousel-btn.prev');
    const nextBtn = document.querySelector('.carousel-btn.next');
    let currentIndex = 0;

    function updateCarousel() {
      carouselContainer.style.transform = `translateX(-${currentIndex * 100}%)`;
    }

    if (prevBtn && nextBtn) {
      prevBtn.addEventListener('click', () => {
        currentIndex = (currentIndex > 0) ? currentIndex - 1 : slides.length - 1;
        updateCarousel();
      });

      nextBtn.addEventListener('click', () => {
        currentIndex = (currentIndex < slides.length - 1) ? currentIndex + 1 : 0;
        updateCarousel();
      });
    }

    // Swipe support
    let touchStartX = 0;
    let touchEndX = 0;

    carouselContainer.addEventListener('touchstart', e => {
      touchStartX = e.changedTouches[0].screenX;
    }, {passive: true});

    carouselContainer.addEventListener('touchend', e => {
      touchEndX = e.changedTouches[0].screenX;
      handleSwipe();
    }, {passive: true});

    function handleSwipe() {
      if (touchEndX < touchStartX - 50) {
        currentIndex = (currentIndex < slides.length - 1) ? currentIndex + 1 : 0;
        updateCarousel();
      }
      if (touchEndX > touchStartX + 50) {
        currentIndex = (currentIndex > 0) ? currentIndex - 1 : slides.length - 1;
        updateCarousel();
      }
    }
  }

  // Floor / Treadmill Toggle
  const toggleBtns = document.querySelectorAll('.toggle-btn');
  const toggleContents = document.querySelectorAll('.toggle-content');
  if (toggleBtns.length > 0 && toggleContents.length > 0) {
    toggleBtns.forEach(btn => {
      btn.addEventListener('click', () => {
        // Remove active class from all
        toggleBtns.forEach(b => b.classList.remove('active'));
        toggleContents.forEach(c => c.classList.remove('active'));

        // Add active class to clicked
        btn.classList.add('active');
        const targetId = btn.getAttribute('data-target');
        document.getElementById(targetId).classList.add('active');
      });
    });
  }

  // Instructor Filtering
  const filterBtns = document.querySelectorAll('.filter-btn');
  const instructorCards = document.querySelectorAll('.instructor-card');
  if (filterBtns.length > 0) {
    filterBtns.forEach(btn => {
      btn.addEventListener('click', () => {
        filterBtns.forEach(b => b.classList.remove('active'));
        btn.classList.add('active');

        const filter = btn.getAttribute('data-filter');

        instructorCards.forEach(card => {
          if (filter === 'all' || card.getAttribute('data-location') === filter) {
            card.style.display = 'block';
          } else {
            card.style.display = 'none';
          }
        });
      });
    });
  }

  // FAQ Accordion
  const accordionHeaders = document.querySelectorAll('.accordion-header');
  if (accordionHeaders.length > 0) {
    accordionHeaders.forEach(header => {
      header.addEventListener('click', () => {
        const item = header.parentElement;
        const isActive = item.classList.contains('active');

        // Close all
        document.querySelectorAll('.accordion-item').forEach(i => {
          i.classList.remove('active');
        });

        // Toggle clicked
        if (!isActive) {
          item.classList.add('active');
        }
      });
    });
  }
});
